TmGeneratedLexer::TmGeneratedLexer(absl::string_view input_source) {
  source_ = input_source;
  Rewind(offset_);
}

Token TmGeneratedLexer::Next() {
restart:
  token_line_ = line_;
  token_offset_ = offset_;

  int state = 0;
  int backupRule = -1;
  uint64_t backupOffset;
  while (state >= 0) {
    int curr_class;
    if (input_rune_ < 0) {
      state = tmLexerAction[state * tmNumClasses];
      if (state > tmFirstRule && state < 0) {
        state = (-1 - state) * 2;
        backupRule = tmBacktracking[state];
        backupOffset = offset_;
        state = tmBacktracking[state + 1];
      }
      continue;
    } else if (input_rune_ < tmRuneClassLen) {
      curr_class = tmRuneClass[input_rune_];
    } else {
      curr_class = 1;
    }
    state = tmLexerAction[state * tmNumClasses + curr_class];
    if (state > tmFirstRule) {
      if (state < 0) {
        state = (-1 - state) * 2;
        backupRule = tmBacktracking[state];
        backupOffset = offset_;
        state = tmBacktracking[state + 1];
      }
      if (input_rune_ == '\n') {
        line_++;
      }

      // Scan the next character.
      offset_ = scan_offset_;
      if (offset_ < source_.size()) {
        input_rune_ = static_cast<unsigned char>(source_[scan_offset_++]);
      } else {
        input_rune_ = -1;
      }
    }
  }

  int rule = tmFirstRule - state;
recovered:

  Token tok = Token(tmToken[rule]);
  bool space = false;
  switch (rule) {
  case 0:
      if (backupRule >= 0) {
        rule = backupRule;
        Rewind(backupOffset);
      } else if (offset_ == token_offset_) {
        if (input_rune_ == -1) {
          tok = Token::EOI;
        }
        Rewind(scan_offset_);
      }
      if (rule != 0) {
        goto recovered;
      }
    break;
  case 2: // invalid_token: /{unclosed_string_literal}/
{ SetUnclosedError("string literal"); }
    break;
  case 3: // invalid_token: /{unclosed_triple_quoted_string_literal}/
{ SetTripleUnclosedError("string literal"); }
    break;
  case 4: // invalid_token: /{unclosed_raw_string_literal}/
{ SetUnclosedError("raw string literal"); }
    break;
  case 5: // invalid_token: /{unclosed_triple_quoted_raw_string_literal}/
{ SetTripleUnclosedError("raw string literal"); }
    break;
  case 6: // invalid_token: /{unclosed_bytes_literal}/
{ SetUnclosedError("bytes literal"); }
    break;
  case 7: // invalid_token: /{unclosed_triple_quoted_bytes_literal}/
{ SetTripleUnclosedError("bytes literal"); }
    break;
  case 8: // invalid_token: /{unclosed_raw_bytes_literal}/
{ SetUnclosedError("raw bytes literal"); }
    break;
  case 9: // invalid_token: /{unclosed_triple_quoted_raw_bytes_literal}/
{ SetTripleUnclosedError("raw bytes literal"); }
    break;
  case 10: // invalid_token: /{unclosed_escaped_identifier}/
{ SetUnclosedError("identifier literal"); }
    break;
  case 11: // invalid_token: /{cs_comment_begin}/
{ SetUnclosedError("comment"); }
    break;
  case 380: // whitespace_no_comments: /{whitespace_no_comments}/
    space = true;
    break;
  case 381: // eoi: /{eoi}/
{
  /* The location of EOI is always [N, N), where N is the length of the input.
  */
  token_offset_ = offset_;
  return Token::EOI;
}
    break;
  case 382: // catch_all: /./
{
  SetOverrideError(
        LastTokenLocationWithStartOffset(),
        absl::StrFormat(R"(Syntax error: Illegal input character "%s")",
                        absl::CEscape(Text().substr(0, 1))));
}
    break;
  }
  if (space) {
    goto restart;
  }
  return tok;
}

void TmGeneratedLexer::Rewind(int64_t rewind_offset) {
  if (rewind_offset < offset_) {
    for (int64_t i = rewind_offset; i < offset_; ++i) {
      if (source_[i] == '\n') {
        line_--;
      }
    }
  } else {
    if (rewind_offset > source_.size()) {
      rewind_offset = source_.size();
    }
    for (int64_t i = offset_; i < rewind_offset; ++i) {
      if (source_[i] == '\n') {
        line_++;
      }
    }
  }

  // Scan the next character.
  scan_offset_ = rewind_offset;
  offset_ = rewind_offset;
  if (offset_ < source_.size()) {
    input_rune_ = static_cast<unsigned char>(source_[scan_offset_++]);
  } else {
    input_rune_ = -1;  // Invalid rune for end of input
  }
}

